# The briefing and checks lists of climb batch 32's rungs (CLIMB-BATCH-32.md, section 1, "The manifest, rung by
# rung"), made from plan-31/manifest/lists31.py for the batch workflow
# (explorations/coordinator/process-engineering/batch-redesign.md, "The brief"): each list holds what the rung's
# section cites, the decisions, the ledger rows, the notes and the code it rests on, and no process position or
# harness fact, which the brief's role text and the fortress-repo skill carry. POSITIONS and FACTS entries are keyed
# by their numbers. Each briefing entry is its facts-extract.sh key, one line on why it is there, and CHECK where the
# record marks it (check): the checks list, read by the skeptic, a repair round and a judge, is those keys in order.
# No key holds a backslash, a backtick, a dollar sign or a double quote, which the script refuses; facts-extract
# matches a heading without its backticks.
# Changed from lists31.py: the record has one run, climb batch 32, the rungs P, S, C, F and B (and, since the
# amendment below, N and D), so there is no --run. The keys are each rung's briefing bullets in section 1, in
# their order, each as the record writes it, its backticks dropped and REC, REV, PRB, NEQ, MCC, SPEC and SRC spelled out as
# section 1's opening paragraph gives them, each with the record's reason, its first letter capitalized unless the
# reason opens with code; a check is marked on its entry. The forks: the record's one forks key, REC "Forks the
# batch takes", section 3's forks whole, in every briefing once, as a check (added to the record by the check of
# 2026-11-15, coordinator/climb-batch-32-review.md, change 10). Rung P's four keys on row 177, the type on a mutable
# local, went with the row, which the coordinator's ruling of 2026-11-15 took out of the rung.
# Amended 2026-11-15: rungs N and D, with their lists as plan-31/manifest/lists31.py has them, moved into this
# batch with their sections (the record's head); their forks key is this record's, and NEQ and MCC are spelled out.
# Fork W (the record's section 3, "The consequential forks") stands at (a), walk now, and the lists are the record's.
# lists(ids, fork_w='b') gives rung N's lists for way (b), walk waits, as lists31.py did: the key of walk's choice for
# a call with a numeral, which the rung then does not edit, is left out, and the reasons of P-59 and of rows 973 and
# 966 say that walk stays (W_B, below); gen32.py --fork-w b makes the same changes in a copy of the record, so that
# check32.js --fork-w b finds the two alike. `python3 -B lists32.py [--fork-w a|b]` checks the keys for that answer.
# lists(ids) gives the lists of the rungs ids, a rung left out by --without dropping from the block; LISTS and REASONS
# are lists(IDS).
# `python3 -B lists32.py` checks every key with facts-extract.sh --check (each must match exactly one place) and
# every reason's form, in $FORTRESS_HOME (this checkout by default), and prints the bytes of each rung's forks key;
# it is run again on the tree the batch is cut from.
import os
SRC = 'ProjectFortress/src/com/sun/fortress/'
REC = "doc:explorations/coordinator/CLIMB-BATCH-32.md#"
REV = "doc:explorations/reviews/c4-fortress-way-2026-11-15.md#"
PRB = "doc:explorations/compile-ladder/plan-32/PROBES.md#"
NEQ = "doc:explorations/reviews/numeral-equality-ways-2026-11-10.md#"
MCC = "doc:explorations/compile-ladder/plan-31/probes/model-closure-check.md#"
SPEC = "doc:Specification/"
_ROOT = os.environ.get('FORTRESS_HOME', os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '../../../..')))
CHECK = True
# The record's one forks key, section 3's "Forks the batch takes" whole, which every rung reads.
======
# Made from plan-31/manifest/gen31.py for climb batch 32, whose record holds one run: climb batch 32, the rungs
# P, S, C, F and B, and, since the record's amendment of 2026-11-15, N and D, which moved here from climb batch 31's
# record with gen31.py's --fork-w. --without <rung> leaves a rung out of the block. A rung's section runs from its heading to the
# next ### heading, as check32.js reads it.
# Changed from gen31.py: the batch's values (the record CLIMB-BATCH-32.md, the lists lists32.py, the output under
# $OUT32); no --run, since the record has one run; the "Fields common to the seven rungs", whose joins-the-gate
# field gives none but the specification's build at the gather, for C's and N's text, and whose lands-only-with
# field reads "none. Every rung lands on its own."; the intro, which is the whole of section 6's "What every agent
# reads first".
# --fork-w a|b is the answer to fork W (the record's section 3, "The consequential forks"), which rung N's block
# depends on. The record is written for (a), walk now, at which the fork stands. At (b), walk waits, the generator
# first makes the changes of W_B_RECORD (below) in the record's text, writes the changed record to
# $OUT32/CLIMB-BATCH-32-fork-w-b.md, and generates from it, with lists32.py's lists for (b). The block is written to
# $OUT32/manifest32.js at (a) and to $OUT32/manifest32-fork-w-b.js at (b). The two blocks as generated on 2026-11-15
# are kept beside this file, block32.js and block32-fork-w-b.js: the batch had no go then, and neither was spliced
# into the script.
# Generates the MANIFEST block for the batch workflow (explorations/coordinator/climb-batch-workflow.js;
# explorations/coordinator/process-engineering/batch-redesign.md) from the record, read at run time, and the
# briefings of lists32.py; check32.js checks it and splices it. On batch 15's pattern (plan-15/manifest/gen15.py):
# each rung's section of the record's section 4 goes into the block word for word as the rung's section, which
# every role on the rung reads (the worker, the skeptic, a judge and a repair round), its code-span backticks
# dropped, any ellipsis character written as three full stops and any minus sign as a hyphen-minus; the briefing's
# reasons go beside the keys, and the script renders them at the end of the worker's brief. No value is set at
# launch: the gather numbers the batch's new rows through ledger.py, so the block has no LEDGER_FROM.
#   python3 -B gen32.py [--fork-w a|b] [--without <rung>]... [RECORD]   RECORD defaults to explorations/coordinator/CLIMB-BATCH-32.md
import json, re, sys, os
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from lists32 import lists, IDS as ALL_IDS

ROOT = os.environ.get('FORTRESS_HOME', os.path.abspath(os.path.join(HERE, '../../../..')))
argv = sys.argv[1:]
USAGE = 'usage: gen32.py [--fork-w a|b] [--without <rung>]... [RECORD]'
FORK_W = 'a'
if '--fork-w' in argv:
    FORK_W = argv[argv.index('--fork-w') + 1]
    del argv[argv.index('--fork-w'):argv.index('--fork-w') + 2]
assert FORK_W in ('a', 'b'), USAGE
RUN_IDS = ALL_IDS
WITHOUT = []
while '--without' in argv:
    WITHOUT.append(argv[argv.index('--without') + 1])
    del argv[argv.index('--without'):argv.index('--without') + 2]
args = [a for a in argv if not a.startswith('--')]
assert all(w in RUN_IDS for w in WITHOUT), ('--without names a rung not in the run', WITHOUT)
IDS = tuple(r for r in RUN_IDS if r not in WITHOUT)
LISTS, REASONS = lists(IDS, FORK_W)
BATCH = '32'
BATCH_RECORD = 'explorations/coordinator/CLIMB-BATCH-32.md'
BRIEFING_LISTS = 'explorations/compile-ladder/plan-32/manifest/lists32.py'
REC = args[0] if args else os.path.join(ROOT, BATCH_RECORD)
OUTDIR = os.environ.get('OUT32', os.path.join(ROOT, 'tmp'))
# The block differs with the answer to fork W, so at (b) its file names the answer.
SUFFIX = '-fork-w-b' if FORK_W == 'b' else ''
OUT = os.path.join(OUTDIR, 'manifest32%s.js' % SUFFIX)
os.makedirs(OUTDIR, exist_ok=True)
rec = open(REC, encoding='utf-8').read()

# Fork W at (b), walk waits (the record's section 3, "The consequential forks"; section 6, "Before the launch",
